var path = Path.Combine(Path.GetTempPath(), "orders.csv");
Export(path, ["1,10.50", "2,42.00"]);
Console.WriteLine(new FileInfo(path).Length); // 0: rows still buffered
Export(path, ["3,7.25"]); // IOException: file is in use by another process

static void Export(string path, string[] rows)
{
    var writer = new StreamWriter(path); // opens an OS file handle
    foreach (var row in rows)
    {
        writer.WriteLine(row);
    }
    // no Dispose: nothing flushes the buffer or closes the handle
}

var path = Path.Combine(Path.GetTempPath(), "orders.csv");
Export(path, ["1,10.50", "2,42.00"]);
Console.WriteLine(new FileInfo(path).Length); // 18: both rows are on disk
Export(path, ["3,7.25"]); // works: the first handle is closed

static void Export(string path, string[] rows)
{
    using var writer = new StreamWriter(path); // disposed when Export returns
    foreach (var row in rows)
    {
        writer.WriteLine(row);
    }
} // Dispose flushes the buffer, then closes the handle, even after an exception

