public sealed class OrderExporter(string path) : IDisposable
{
    private readonly StreamWriter _writer = new(path); // created here: owned

    public void Write(string row) => _writer.WriteLine(row);

    public void Dispose() => _writer.Dispose(); // pass the cleanup on
}
